window.startDoaTeduh=function(){'use strict';
const data=window.DOA_DATA, root=document.getElementById('app');
if(!data){root.textContent='Data doa tidak dapat dimuat. Pastikan data.js berada di folder yang sama.';return}
const S={view:'home',phase:1,explore:'phase',filter:'semua',query:'',reader:'',quickId:'',dailyCategory:'semua',guideContext:'general',guideMode:'short',guideStep:0,salatMode:'full',salatDone:[],salatCounts:{},palette:'sage',readingFrom:'home',previousScroll:0,font:31,baseFont:16,latin:true,translation:true,sources:true,dark:false,focus:false,saved:[],done:[],last:'',install:null,searchLimit:40,prefsOpen:false};
const PREF='doa-teduh-state-v2';
try{Object.assign(S,JSON.parse(localStorage.getItem(PREF)||'{}'))}catch(e){}
S.saved=Array.isArray(S.saved)?S.saved:[];S.done=Array.isArray(S.done)?S.done:[];S.salatDone=Array.isArray(S.salatDone)?S.salatDone:[];S.salatCounts=(S.salatCounts&&typeof S.salatCounts==='object'&&!Array.isArray(S.salatCounts))?S.salatCounts:{};
const extras=window.DOA_EXTRAS||{items:[],moments:[]}, quick=extras.items, moments=extras.moments, quickMap=new Map(quick.map(x=>[x.id,x]));
const guideData=window.DOA_GUIDE||{flows:{}}, guideFlows=guideData.flows;const salatData=window.DOA_SALAT||{short:[],full:[],custom:[]};const salatMap=new Map([...quick,...salatData.custom].map(x=>[x.id,x]));
const chs=data.chapters;const secs=chs.flatMap(c=>c.sections.map(s=>({...s,phaseTitle:c.shortTitle})));const byId=new Map(secs.map(s=>[s.id,s]));// Dedicated reader uses the exact original final munajat, not a second edited copy.
const closing=byId.get('asma-99');
const closingStart=closing?.blocks.findIndex(b=>b.text==='Paragraf Doa Penutup Fase 13 - Penyerahan Diri Sepenuhnya')??-1;
const closingEnd=closing?.blocks.findIndex((b,i)=>i>closingStart&&b.text==="Aamiin, aamiin, aamiin, ya Rabbal 'Aalamiin.")??-1;
if(closingStart<0||closingEnd<=closingStart)throw Error('Doa Penutup Agung not found in original source');
const personalBlocks=closing.blocks.slice(closingStart,closingEnd+1);
const translationStart=personalBlocks.findIndex(b=>b.type==='label'&&b.text==='Terjemahan Indonesia Lengkap');
// Preserve every word; only classify the Indonesian paragraphs so the existing
// translation visibility setting works for every hajat.
const personalLong={...closing,id:'doa-pribadi-panjang',type:'personal',number:null,variant:1,title:'Doa Pribadi Lengkap — Doa Penutup Agung',arabicTitle:'',subtitle:'Munajat lengkap dengan sembilan hajat utama · dari Fase 13',blocks:personalBlocks.map((b,i)=>i>translationStart&&translationStart>=0&&b.type==='text'?{...b,type:'translation'}:b),warnings:['Ini munajat susunan pribadi dari naskah asli, bukan satu hadis Nabi ﷺ. Lafal pembuka merujuk pada perjalanan 99 Asmaul Husna; tahun dan target tertentu dipertahankan persis seperti naskah. Sesuaikan hajat saat berdoa bila perlu.']};
byId.set(personalLong.id,personalLong);
const asma=secs.filter(s=>s.type==='asma');const nUnique=new Set(asma.map(s=>s.number)).size;
function persist(){try{localStorage.setItem(PREF,JSON.stringify({font:S.font,baseFont:S.baseFont,latin:S.latin,translation:S.translation,sources:S.sources,dark:S.dark,saved:S.saved,done:S.done,last:S.last,phase:S.phase,explore:S.explore,palette:S.palette,dailyCategory:S.dailyCategory,guideContext:S.guideContext,guideMode:S.guideMode,salatMode:S.salatMode,salatDone:S.salatDone,salatCounts:S.salatCounts}))}catch(e){}}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function ico(id){const d={home:'M3 10.5 12 3l9 7.5V21h-6v-6H9v6H3z',book:'M4 19.5A2.5 2.5 0 0 1 6.5 17H20M6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5v14A2.5 2.5 0 0 0 6.5 22H20',search:'m21 21-4.34-4.34M11 19a8 8 0 1 0 0-16 8 8 0 0 0 0 16',bookmark:'M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z',check:'M20 6 9 17l-5-5',chevron:'m9 18 6-6-6-6',back:'m15 18-6-6 6-6',moon:'M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13z',sun:'M12 3v2m0 14v2M4.2 4.2l1.4 1.4m12.8 12.8 1.4 1.4M3 12h2m14 0h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4M16.4 12a4.4 4.4 0 1 1-8.8 0 4.4 4.4 0 0 1 8.8 0',shield:'M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6',close:'M18 6 6 18M6 6l12 12',settings:'M3 12h18M7 6v12M17 6v12',maximize:'M8 3H5a2 2 0 0 0-2 2v3m13-5h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3m13-5v3a2 2 0 0 1-2 2h-3',copy:'M8 8h12v12H8zM4 16H3V4h12v1',share:'M12 16V2m-5 5 5-5 5 5M5 13v8h14v-8',info:'M12 17v-5m0-4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${d[id]||d.info}"/></svg>`}
function btn(action,label,cls='',attrs=''){return `<button class="${cls}" data-action="${action}" ${attrs}>${label}</button>`}
function announce(t){document.querySelector('.toast')?.remove();let x=document.createElement('div');x.className='toast';x.role='status';x.textContent=t;document.body.appendChild(x);setTimeout(()=>x.remove(),2400)}
function normalize(s){return String(s??'').normalize('NFKD').replace(/[\u0300-\u036f\u064B-\u065F\u0670]/g,'').toLowerCase().replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه')}
const indexes=[personalLong,...secs].map(s=>({id:s.id,section:s,hay:normalize([s.title,s.subtitle,s.phaseTitle,s.arabicTitle,...s.blocks.map(b=>b.text||b.rows?.map(r=>r.join(' ')).join(' ')||'')].join(' '))}));
function chapter(n){return chs.find(c=>c.number===Number(n))||chs[0]}
function numAsma(ch){return ch.sections.filter(s=>s.type==='asma').length}
function label(s){return s.type==='asma'?`${s.title}${s.variant>1?' · versi 2':''}`:s.title}
function itemLabel(id){return quickMap.get(id)?.title||byId.get(id)?.title||'Doa'}
function secondary(s){return s.type==='asma'?s.subtitle:`Fase ${s.chapter} • ${s.phaseTitle}`}
function nav(){return `<nav class="nav-dock" aria-label="Navigasi utama">${[['home','Beranda','home'],['guide','Alur Doa','list'],['daily','Doa Pilihan','book'],['explore','Jelajah','home'],['saved','Simpan','bookmark']].map(([a,l,i])=>btn('nav',`${ico(i)}<span>${l}</span>`,`nav-btn ${(S.view===a||(a==='guide'&&S.view==='salatbundle'))?'active':''}`,`data-target="${a}" aria-label="${l}"`)).join('')}</nav>`}
function shell(inner){const reading=['read','quickread','salatbundle'].includes(S.view);const tt=reading?(S.view==='salatbundle'?'Rangkaian Setelah Salat':S.view==='quickread'?quickMap.get(S.quickId)?.title:byId.get(S.reader)?.title):'';return `<header class="topbar"><div class="shell toprow">${reading?`${btn('return',`${ico('back')}<span>Kembali</span>`,'sticky-back','aria-label="Kembali ke daftar bacaan"')}<span class="top-reader-label" aria-label="Halaman saat ini: ${esc(tt||'Sedang membaca')}">${esc(tt||'Sedang membaca')}</span>`:`<button class="brand" data-action="nav" data-target="home"><span class="brand-icon" aria-hidden="true">۞</span><span><h1>Doa Teduh</h1><small>Ruang berdoa</small></span></button>`}<div class="actions">${btn('theme',ico(S.dark?'sun':'moon'),'icon-btn',`aria-label="${S.dark?'Mode terang':'Mode gelap'}" title="Ganti tema"`)}${btn('nav',ico('search'),'icon-btn','data-target="search" aria-label="Cari doa"')}</div></div></header><div class="reading-progress"><span id="prog"></span></div><main class="shell page">${inner}</main>${nav()}${S.focus&&reading?btn('focus',`${ico('close')} Keluar fokus`,'focus-exit','aria-label="Keluar dari mode fokus"'):''}`}

function sectionCard(s){return `<button class="result" data-action="read" data-id="${esc(s.id)}"><div class="index-n">${s.type==='asma'?s.number:(s.type==='intro'?'✦':'•')}</div><div class="txt"><strong>${esc(label(s))}</strong><small>${esc(secondary(s))} • ${s.blocks.length} bagian bacaan</small></div>${S.done.includes(s.id)?`<span class="badgetiny">Selesai</span>`:''}${ico('chevron')}</button>`}
function chapterCard(c){return `<button class="chapter-card" data-action="phase" data-n="${c.number}"><span class="index-n">${String(c.number).padStart(2,'0')}</span><span class="chapter-info"><strong>${esc(c.shortTitle)}</strong><small>${c.number===13?'3 nama':`${Math.max(0,(c.number-1)*8+1)}–${Math.min(99,c.number*8)} Asmaul Husna`} · ${c.sections.length} bacaan</small></span><span class="chevron">${ico('chevron')}</span></button>`}
function home(){const finished=secs.filter(s=>S.done.includes(s.id)).length;const last=byId.get(S.last);return `<section class="adab-lead card home-welcome"><div class="adab-topline"><span>AWALI DENGAN ADAB</span><span class="adab-flower" aria-hidden="true">✧</span></div><h2>Berdoa dengan hati yang tenang.</h2><p>Tenangkan hati, mohon ampun, puji Allah, bershalawat, lalu sampaikan harapan dengan penuh keyakinan. Tidak perlu tergesa-gesa.</p><div class="adab-chips"><span>Istighfar</span><span>Pujian</span><span>Shalawat</span><span>Doa</span><span>Penutup</span></div>${btn('nav',`Mulai panduan berdoa ${ico('chevron')}`,'btn home-main-cta','data-target="guide"')}<small class="adab-disclaimer">Panduan membaca, bukan tata cara wajib dengan urutan tetap.</small></section><div class="section-head home-library-title"><div><h2>Apa yang ingin Anda baca?</h2><p>Buka doa pilihan atau lanjutkan perjalanan lengkap</p></div></div><div class="home-paths"><button class="home-path card salat-home-path" data-action="salat-open"><span class="home-path-icon">☪</span><span><strong>Rangkaian setelah salat</strong><small>Mulai atau lanjutkan zikir dan doa berurutan · penghitung 33×</small></span>${ico('chevron')}</button><button class="home-path card personal-home-path" data-action="read" data-id="doa-pribadi-panjang"><span class="home-path-icon">✦</span><span><strong>Doa pribadi lengkap</strong><small>Munajat panjang asli · sembilan hajat · Arab, Latin dan arti</small></span>${ico('chevron')}</button><button class="home-path card" data-action="nav" data-target="daily"><span class="home-path-icon">☾</span><span><strong>Doa pilihan</strong><small>${quick.length} doa terpilih menurut kebutuhan</small></span>${ico('chevron')}</button><button class="home-path card" data-action="nav" data-target="explore"><span class="home-path-icon">13</span><span><strong>Perjalanan 13 fase</strong><small>99 Asmaul Husna dan naskah lengkap</small></span>${ico('chevron')}</button></div>${last?`<div class="card keep-reading home-resume"><div><div class="eyebrow" style="margin-bottom:3px">LANJUTKAN MEMBACA</div><h3>${esc(label(last))}</h3><p>Fase ${last.chapter}</p></div>${btn('read',`Lanjut ${ico('chevron')}`,'btn small',`data-id="${esc(last.id)}"`)}</div>`:''}<div class="stats home-stats"><div class="stat card"><strong>13</strong><small>Fase</small></div><div class="stat card"><strong>${nUnique}</strong><small>Nama unik</small></div><div class="stat card"><strong>${finished}</strong><small>Selesai dibaca</small></div></div><div class="section-head"><div><h2>Perjalanan doa</h2><p>Dari taubat hingga penyerahan diri</p></div>${btn('nav','Lihat semuanya','inline-link','data-target="explore"')}</div><div class="chapter-grid">${chs.map(chapterCard).join('')}</div><div class="notice" style="margin-top:19px">${ico('info')}<div><strong>Dalil dipisahkan dari munajat pribadi</strong>Doa yang tersusun sendiri tetap dapat dibaca sebagai doa umum yang baik, tetapi bukan otomatis hadis Nabi ﷺ. Naskah 13 fase masih memerlukan audit menyeluruh.</div></div><div class="footer">Tanpa iklan · Seluruh doa pribadi sudah tersedia<br>${btn('nav','Catatan verifikasi & sumber','text-link','data-target="review"')}</div>`}
function explore(){if(S.explore==='asma')return `<div class="eyebrow">JELAJAH PUSTAKA</div><h2 class="heading">99 Asmaul Husna</h2><p class="fineprint">Urutan mengikuti dokumen. Nama nomor 34 dan 35 masing-masing mempunyai dua versi teks dalam naskah.</p>${exploreTabs()}<div class="names">${asma.map(s=>`<button class="name-card" data-action="read" data-id="${s.id}"><span class="num">${String(s.number).padStart(2,'0')}${s.variant>1?' · V2':''}</span><span class="ar" lang="ar" dir="rtl">${esc(s.arabicTitle)}</span><span class="latin">${esc(s.title)}</span><span class="meaning">${esc(s.subtitle)}</span></button>`).join('')}</div>`;
 const c=chapter(S.phase);return `<div class="eyebrow">JELAJAH PUSTAKA</div><h2 class="heading">Baca menurut fase</h2>${exploreTabs()}<div class="filter-row" aria-label="Pilih fase">${chs.map(x=>btn('phasechip',`Fase ${x.number}`,x.number===c.number?'active':'',`data-n="${x.number}"`)).join('')}</div><div class="phase-head card"><div class="eyebrow">FASE ${String(c.number).padStart(2,'0')} DARI 13</div><h2>${esc(c.shortTitle)}</h2><p>${numAsma(c)} bacaan Asmaul Husna dan materi pendukung. Pilih bacaan di bawah.</p><div class="progress-track"><span style="width:${Math.round(c.sections.filter(s=>S.done.includes(s.id)).length/c.sections.length*100)}%"></span></div></div><div class="detail-list">${c.sections.map(sectionCard).join('')}</div>`}
function exploreTabs(){return `<div class="segmented">${btn('explore-tab','Berdasarkan fase',S.explore==='phase'?'active':'','data-tab="phase"')}${btn('explore-tab','99 Asmaul Husna',S.explore==='asma'?'active':'','data-tab="asma"')}</div>`}
function quickCard(x){return `<button class="quick-card card" data-action="quickread" data-id="${esc(x.id)}"><span class="quick-glyph">${x.kind==='Al-Qur’an'?'۞':x.kind==='Doa susunan pribadi'?'✦':'☾'}</span><span class="quick-card-body"><strong>${esc(x.title)}</strong><small>${esc(x.reference)} · ${esc(x.when)}</small></span>${ico('chevron')}</button>`}
function daily(){const cats=[['semua','Semua'],['utama','Inti doa'],['salat','Setelah salat'],['pagi','Pagi–petang'],['perlindungan','Perlindungan'],['iman','Iman'],['rezeki','Rezeki & ilmu'],['hujan','Hujan'],['keluarga','Keluarga'],['pribadi','Doa pribadi'],['adab','Adab & pembuka']];const chosen=quick.filter(x=>S.dailyCategory==='semua'||x.category===S.dailyCategory);return `<div class="eyebrow">DOA PILIHAN · DITELUSURI SUMBERNYA</div><h2 class="heading">Doa untuk setiap keadaan</h2><p class="fineprint">${quick.length} bacaan pilihan dengan teks, makna, serta tautan ayat atau hadis. <b>Doa pribadi ditandai terpisah</b> dan tidak dinisbatkan kepada Nabi ﷺ.</p><div class="section-head"><div><h2>Kumpulan doa</h2><p>Pilih sesuai keadaan</p></div>${btn('nav','Catatan dalil','inline-link','data-target="review"')}</div><div class="filter-row daily-filters">${cats.map(([key,label])=>btn('daily-filter',label,S.dailyCategory===key?'active':'',`data-filter="${key}"`)).join('')}</div>${S.dailyCategory==='salat'?`<div class="salat-daily-cta card"><strong>Baca sebagai satu rangkaian</strong><p>Ikuti zikir dan doa setelah salat dari awal sampai penutup, tidak perlu membuka kartu satu-satu.</p>${btn('salat-open','Buka rangkaian setelah salat →','btn')}</div>`:''}<div class="detail-list">${chosen.map(x=>x.id==='pilihan-pribadi-ringkas'?sectionCard(personalLong)+quickCard(x):quickCard(x)).join('')}</div><div class="section-head"><div><h2>Waktu-waktu utama</h2><p>Pilih momen berdoa berdasarkan dalil</p></div></div><div class="moments-grid">${moments.map(x=>`<article class="moment card"><strong>${esc(x.title)}</strong><p>${esc(x.description)}</p><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.source)} ↗</a>${btn('quickread','Baca doa yang cocok','moment-go',`data-id="${esc(x.quick[0])}"`)}</article>`).join('')}</div><p class="fineprint" style="margin:25px 0">Catatan: waktu yang dianjurkan berdoa tidak berarti ada satu lafal khusus atau jaminan mekanis bahwa setiap permohonan pasti diberikan persis seperti yang diminta.</p></div>`}
function guide(){const conf=guideFlows[S.guideContext]||guideFlows.general;const steps=(S.guideMode==='full'?conf.full:conf.short).map(id=>quickMap.get(id)).filter(Boolean);S.guideStep=Math.min(Math.max(0,S.guideStep),steps.length-1);const ix=S.guideStep;const x=steps[ix];const how=S.guideContext==='salat'?'Mulai dengan zikir pascasalam.':S.guideContext==='rain'?'Mulai dengan doa saat hujan.':'Siapkan hati sebelum memohon.';const note=ix===0?'Jangan tergesa-gesa. Hadirkan hati dan pahami maknanya.':x?.id==='adab-asma-agung'?'Bacaan ini memiliki hadis sahih tentang nama Allah yang agung; bukan rumus wajib pengabulan.':x?.id==='adab-penutup'?'Ayat ini dibaca sebagai pujian pilihan, bukan penutup baku setiap doa.':'Baca perlahan, dan hayati artinya sebelum melanjutkan.';
return `<div class="guide-page"><div class="eyebrow">PANDUAN BERDOA • TIDAK TERGESA</div><h2 class="heading">Dari awal hingga penutup</h2><p class="fineprint">Ikuti secara bertahap, tidak perlu terburu-buru. Setiap bacaan bersumber sendiri-sendiri; <b>rangkaian keseluruhannya adalah susunan editorial, bukan satu amalan dengan bilangan atau urutan wajib.</b></p><div class="guide-contexts" aria-label="Pilih keadaan">${[['general','Doa umum'],['rain','Saat hujan']].map(([id,lab])=>btn('guide-context',lab,S.guideContext===id?'active':'',`data-context="${id}"`)).join('')}${btn('salat-open','Sesudah salat · paket berurutan ↗','guide-salat-entry')}</div><div class="guide-context-intro card"><strong>${esc(conf.title)}</strong><p>${esc(conf.hint)}</p><div class="guide-modes">${btn('guide-mode','Ringkas',S.guideMode==='short'?'active':'','data-mode="short"')}${btn('guide-mode','Lebih lengkap',S.guideMode==='full'?'active':'','data-mode="full"')}</div></div><div class="guide-progress-head"><span>TAHAP ${ix+1} DARI ${steps.length}</span><span>${Math.round((ix+1)/steps.length*100)}%</span></div><div class="guide-progress"><span style="width:${((ix+1)/steps.length*100).toFixed(1)}%"></span></div><article id="guide-reader" class="guide-reader card"><div class="guide-step-header"><span class="step-circle">${String(ix+1).padStart(2,'0')}</span><div><span class="eyebrow">${esc(x.kind)} · ${esc(x.category)}</span><h3>${esc(x.title)}</h3></div></div><p class="guide-coach">${esc(ix===0?how:note)}</p><div class="guide-appearance">${btn('settings',`${ico('settings')} ${S.prefsOpen?'Tutup pengaturan':'Atur teks & warna'}`,'mini-btn')}${S.prefsOpen?prefsOptions():''}</div>${x.arabic?`<div class="entry arabic guide-arabic" lang="ar" dir="rtl">${esc(x.arabic)}</div>`:''}${x.latin?`<div class="entry latin guide-latin"><strong>Latin</strong><p>${esc(x.latin)}</p></div>`:''}<div class="guide-meaning"><span>MAKNA / TERJEMAHAN</span><p>${esc(x.meaning)}</p></div><div class="guide-reference"><strong>${esc(x.reference)}</strong>${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Periksa sumber asli ↗</a>`:''}<p>${esc(x.note||'')}</p></div><div class="guide-nav">${ix>0?btn('guide-step',`${ico('back')} Sebelumnya`,'btn outline',`data-step="${ix-1}"`):'<span></span>'}${ix<steps.length-1?btn('guide-step',`Selesai, lanjut ${ico('chevron')}`,'btn',`data-step="${ix+1}"`):btn('guide-restart',`Ulangi dari awal ${ico('chevron')}`,'btn')}</div></article><div class="guide-overview"><h3>Urutan bacaan ${S.guideMode==='short'?'ringkas':'lengkap'}</h3><p>Ketuk tahap mana pun untuk membacanya. Alur ini boleh disesuaikan kebutuhan.</p><div class="guide-steps">${steps.map((it,i)=>btn('guide-step',`<span class="guide-num">${String(i+1).padStart(2,'0')}</span><span>${esc(it.title)}</span>${ico('chevron')}`,`guide-step-btn ${i===ix?'active':''}`,`data-step="${i}"`)).join('')}</div></div><section class="guide-caution card"><strong>Adab yang perlu dijaga</strong><ul><li><b>Ikhlas dan penuh harap</b> kepada Allah, bukan mengejar bacaan seolah mekanisme yang menjamin hasil.</li><li><b>Memuji Allah, kemudian bershalawat, lalu berdoa.</b> Ini memiliki landasan hadis Abu Dawud 1481. Istighfar ditempatkan sebagai persiapan yang dianjurkan, bukan syarat mutlak.</li><li><b>Jangan terburu-buru berputus asa.</b> Tidak mengeluh bahwa doa tak pernah dijawab (Muslim 2735).</li><li><b>Jangan mendoakan dosa dan pemutusan silaturahmi.</b> (Muslim 2735).</li><li><b>Perhatikan konteks.</b> Zikir setelah salam, doa saat sujud, dan doa ketika hujan masing-masing mempunyai tuntunan tersendiri.</li></ul><div class="guide-links"><a href="https://sunnah.com/abudawud:1481" target="_blank" rel="noopener noreferrer">Landasan pembukaan doa ↗</a><a href="https://sunnah.com/muslim:2735c" target="_blank" rel="noopener noreferrer">Larangan tergesa-gesa ↗</a></div></section><section class="guide-optional card"><div class="eyebrow">BACAAN PELENGKAP · BUKAN TAHAP WAJIB</div><h3>Ketika mengakhiri suatu majelis</h3><p>Kafaratul majelis adalah bacaan ketika hendak meninggalkan pertemuan, <b>bukan penutup khusus yang diwajibkan bagi setiap doa pribadi</b>.</p><div class="guide-option-actions">${btn('quickread',`Kafaratul majelis ${ico('chevron')}`,'btn outline','data-id="adab-kafarat-majelis"')}${btn('quickread',`Sayyidul Istighfar ${ico('chevron')}`,'btn outline','data-id="adab-sayyidul-istighfar"')}</div></section><div class="footer">Doa Teduh · sumber Al-Qur’an dan hadis ditandai pada tiap bacaan.</div></div>`}

function salatBundle(){
 const mode=S.salatMode==='short'?'short':'full';const ids=salatData[mode]||[], steps=ids.map((id,index)=>({x:salatMap.get(id),key:`${mode}-${index}`})).filter(v=>v.x);const completed=steps.filter(({key})=>S.salatDone.includes(key)).length;const firstPrayer=steps.findIndex(z=>['adab-hamdalah','pilihan-dunia-akhirat'].includes(z.x.id));const divideAt=firstPrayer<0?steps.length:firstPrayer;
 const total=steps.length;let cards='';
 steps.forEach(({x,key},i)=>{
  if(i===0)cards+=`<section class="salat-group-head" id="salat-zikir"><span>01 · ZIKIR SETELAH SALAM</span><h3>Awali dengan zikir yang diriwayatkan.</h3><p>Setiap bacaan memiliki dalilnya sendiri; susunan lengkap di halaman ini adalah panduan, bukan satu hadis tentang urutan tetap.</p></section>`;
  if(i===divideAt)cards+=`<section class="salat-group-head optional" id="salat-doa"><span>02 · DOA PILIHAN</span><h3>Lanjutkan dengan munajat.</h3><p>Bagian berikut berisi doa dan pujian pilihan. Boleh dibaca setelah zikir atau pada waktu doa lainnya; bukan rangkaian wajib khusus setelah salat.</p></section>`;
  const count=Number(S.salatCounts[key]||0);const marked=S.salatDone.includes(key);const isPersonal=x.kind==='Doa susunan pribadi';const doneClass=marked?'complete':'';
  cards+=`<article class="salat-item card ${doneClass}" id="salat-step-${i+1}" aria-label="Bacaan ${i+1}: ${esc(x.title)}"><div class="salat-item-heading"><span class="salat-step-num">${String(i+1).padStart(2,'0')}</span><div><span class="eyebrow">${esc(x.kind)}${isPersonal?' · bukan hadis':''}</span><h3>${esc(x.title)}</h3></div><span class="salat-done-indicator" aria-label="${marked?'Sudah dibaca':'Belum ditandai'}">${marked?'✓':''}</span></div>${x.arabic?`<div class="salat-arabic entry arabic" dir="rtl" lang="ar">${esc(x.arabic)}</div>`:''}${x.latin?`<div class="salat-latin entry latin"><span>LATIN</span><p>${esc(x.latin)}</p></div>`:''}<div class="salat-meaning entry translation"><span>${isPersonal?'DOA PRIBADI':'ARTI / MAKNA'}</span><p>${esc(x.meaning)}</p></div><div class="salat-source"><span>${esc(x.reference||'Rujukan bacaan')}</span>${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Cek dalil ↗</a>`:''}</div>${x.note?`<p class="salat-note">${esc(x.note)}</p>`:''}${x.id==='pilihan-mengingat-syukur'?'<p class="salat-note salat-priority">Catatan: “dubur salat” pada hadis ini dipahami sebagian ulama sebagai sebelum salam. Jangan menganggap penempatannya di sini sebagai ketetapan tunggal.</p>':''}${x.counter?`<div class="salat-counter"><div><span>Penghitung zikir (opsional)</span><strong aria-live="polite" aria-atomic="true" id="salat-count-${i}">${Math.min(x.counter,Math.max(0,count))} / ${x.counter}</strong></div><div class="salat-counter-actions"><button type="button" class="salat-count-tap" data-action="salat-count" data-key="${esc(key)}" data-n="${i}" data-limit="${x.counter}" aria-label="Tambah hitungan ${esc(x.title)}" ${count>=x.counter?'disabled':''}>${count>=x.counter?'Selesai ✓':'+ 1'}</button><button type="button" class="salat-count-reset" data-action="salat-count-reset" data-key="${esc(key)}" data-n="${i}" aria-label="Ulangi hitungan ${esc(x.title)}">↺</button></div></div>`:''}<div class="salat-item-foot">${btn('salat-mark',marked?'✓ Sudah dibaca':'Tandai dibaca',`salat-mark ${marked?'marked':''}`,`data-key="${esc(key)}" data-n="${i}" aria-pressed="${marked}"`)}${i<total-1?btn('salat-next','Lanjut bacaan ↓','salat-next',`data-n="${i+2}"`):''}</div></article>`;
 });
 return `<div class="salat-page"><div class="salat-page-title"><div class="eyebrow">IBADAH HARIAN · DOA TEDUH</div><h2 class="heading">Rangkaian setelah salat</h2><p class="fineprint">Zikir, lalu doa pilihan—semuanya berurutan dalam satu halaman.</p></div><section class="salat-intro card"><div class="salat-intro-top"><span>SESUDAH SALAM</span><span>Tenang · perlahan · pahami makna</span></div><div class="salat-intro-body"><div><h3>Berzikir dengan khusyuk.</h3><p>Zikir pascasalam berdalil. Doa sesudahnya adalah <strong>pilihan</strong>, bukan paket wajib dengan urutan tetap.</p></div><div class="salat-modes" role="group" aria-label="Pilih panjang rangkaian">${btn('salat-mode','Ringkas',mode==='short'?'active':'',`data-mode="short" aria-pressed="${mode==='short'}"`)}${btn('salat-mode','Lengkap',mode==='full'?'active':'',`data-mode="full" aria-pressed="${mode==='full'}"`)}</div></div><details class="salat-tools-details"><summary>Atur tampilan Arab, Latin & arti</summary><div class="salat-reading-tools" role="group" aria-label="Pengaturan tampilan bacaan"><span class="salat-reading-tools-label">Tampilan</span>${btn('toggle-latin',`Latin ${S.latin?'✓':'○'}`,`salat-appearance-btn ${S.latin?'active':''}`,`aria-pressed="${S.latin}"`)}${btn('toggle-translation',`Arti ${S.translation?'✓':'○'}`,`salat-appearance-btn ${S.translation?'active':''}`,`aria-pressed="${S.translation}"`)}<span class="salat-size-label" aria-label="Ukuran huruf Arab">Arab</span>${btn('salat-font-down','A−','salat-appearance-btn salat-font-btn','aria-label="Perkecil tulisan Arab"')}${btn('salat-font-up','A+','salat-appearance-btn salat-font-btn','aria-label="Perbesar tulisan Arab"')}</div></details><details class="salat-about"><summary>Panduan dan status sumber</summary><p>Bacaan zikir memiliki dalilnya masing-masing. Tidak ada tuntunan bahwa semua bacaan di halaman ini wajib ditamatkan sebagai satu rangkaian. Doa tambahan boleh dipilih sesuai kebutuhan dan tidak menggantikan zikir yang disyariatkan.</p></details></section><div class="salat-toolbar" aria-label="Kemajuan rangkaian"><div><strong id="salat-progress-text" aria-live="polite">${completed}/${total} bacaan ditandai</strong><div class="salat-progress" role="progressbar" aria-label="Kemajuan bacaan" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${completed}" id="salat-progress-track"><span id="salat-progress-bar" style="width:${total?completed/total*100:0}%"></span></div></div><div class="salat-toolbar-actions">${btn('salat-resume',`Lanjut ${ico('chevron')}`,'salat-resume',`aria-label="Lanjutkan ke bacaan yang belum selesai"`)}${btn('salat-reset','Ulangi','salat-reset','aria-label="Mulai ulang seluruh rangkaian"')}</div></div><div class="salat-jump" aria-label="Lompat bagian">${btn('salat-jump','01 Zikir','', 'data-anchor="salat-zikir"')}${mode==='full'?btn('salat-jump','02 Doa pilihan','', 'data-anchor="salat-doa"'):''}</div>${cards}<section class="salat-finish card"><div class="salat-finish-mark" aria-hidden="true">۞</div><h3>Semoga Allah menerima amal dan doa kita.</h3><p>Anda dapat mengakhiri setelah zikir atau memilih sebagian doa sesuai kebutuhan. Tidak wajib menamatkan semua bacaan dalam halaman ini.</p>${btn('salat-reset','Mulai rangkaian baru ↺','btn')} ${btn('nav','Doa pilihan','btn outline','data-target="daily"')}</section><p class="fineprint salat-bottom-note">Setiap rujukan dapat dibuka melalui tautan “Cek dalil”. Terdapat perbedaan pandangan mengenai penempatan sebagian doa sebelum atau sesudah salam.</p></div>`;
}
function salatProgressRefresh(){const mode=S.salatMode==='short'?'short':'full';const count=(salatData[mode]||[]).length;const done=(salatData[mode]||[]).filter((_,i)=>S.salatDone.includes(`${mode}-${i}`)).length;const e=document.getElementById('salat-progress-text'),b=document.getElementById('salat-progress-bar');if(e)e.textContent=`${done}/${count} bacaan ditandai`;if(b)b.style.width=`${count?done/count*100:0}%`;const p=document.getElementById('salat-progress-track');if(p)p.setAttribute('aria-valuenow',done)}

function quickRead(){const x=quickMap.get(S.quickId)||quick[0];if(!x)return daily();const saved=S.saved.includes(x.id);const isDone=S.done.includes(x.id);const ix=quick.findIndex(d=>d.id===x.id);return `<div class="content-width quickreader"><section class="reader-head card"><div class="eyebrow">DOA PILIHAN · ${esc(x.category.toUpperCase())}</div><h2 class="reader-title">${esc(x.title)}</h2><div class="reader-meta"><span class="badgetiny ${x.kind==='Doa susunan pribadi'?'warn':''}">${esc(x.kind)}</span><span class="badgetiny">${esc(x.reference.split(' — ')[0])}</span></div><div class="reader-tools">${btn('save',`${ico('bookmark')} ${saved?'Disimpan':'Simpan'}`,`mini-btn ${saved?'on':''}`)}${btn('done',`${ico('check')} ${isDone?'Selesai':'Tandai selesai'}`,`mini-btn ${isDone?'on':''}`)}${btn('focus',`${ico('maximize')} ${S.focus?'Akhiri fokus':'Fokus'}`,'mini-btn')}${btn('copytext',`${ico('copy')} Salin doa`,'mini-btn')}</div></section><section class="reader-body card">${x.arabic?`<div class="entry label">LAFAL ARAB</div><div class="entry arabic curated-ar" lang="ar" dir="rtl">${esc(x.arabic)}</div>`:''}${x.latin?`<div class="entry label">BACAAN LATIN</div><div class="entry latin">${esc(x.latin)}</div>`:''}<div class="entry label">${x.kind==='Doa susunan pribadi'?'MUNAJAT DALAM BAHASA INDONESIA':'ARTI DAN MAKNANYA'}</div><div class="entry translation">${esc(x.meaning)}</div><div class="source-sheet"><div class="source-label">${ico('shield')} ${x.kind==='Doa susunan pribadi'?'Keterangan asal teks':'Sumber rujukan'}</div><strong>${esc(x.reference)}</strong>${x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Buka sumber asli ↗</a>`:''}</div><div class="when-sheet"><strong>Waktu dan konteks</strong><p>${esc(x.when)}</p></div>${x.note?`<div class="when-sheet subtle"><strong>Catatan pengamalan</strong><p>${esc(x.note)}</p></div>`:''}</section><div class="reader-preferences"><div class="pref-top"><div><strong>Tampilan bacaan</strong><small>Ukuran Arab, Latin, terjemahan, dan warna</small></div>${btn('settings','Atur','mini-btn')}</div>${S.prefsOpen?prefsOptions():''}</div><div class="reading-nav">${ix>0?btn('quickread',`${ico('back')} Sebelumnya`,'btn outline',`data-id="${quick[ix-1].id}"`):'<span></span>'}${ix<quick.length-1?btn('quickread',`Selanjutnya ${ico('chevron')}`,'btn',`data-id="${quick[ix+1].id}"`):''}</div></div>`}
function prefsOptions(){return `<div class="pref-expanded"><label>Ukuran huruf Arab: <strong id="fontNumber">${S.font}px</strong></label><div class="range-row"><span>ع</span><input id="fontSlider" type="range" min="23" max="49" step="2" value="${S.font}" aria-label="Ukuran huruf Arab"><span class="feature-ar">ع</span></div><div class="reader-tools">${btn('toggle-latin',`Latin ${S.latin?'✓':'○'}`,'mini-btn')}${btn('toggle-translation',`Arti ${S.translation?'✓':'○'}`,'mini-btn')}${btn('fontsize','Teks A+/−','mini-btn')}</div><div class="palette-setting"><span>Warna suasana</span><div class="palette-row">${[['sage','Hijau teduh'],['ocean','Biru laut'],['clay','Cokelat hangat']].map(([key,lab])=>btn('palette',`<i class="swatch ${key}"></i>${lab}`,`palette-opt ${S.palette===key?'active':''}`,`data-palette="${key}" aria-label="Tema ${lab}"`)).join('')}</div></div></div>`}
function search(){return `<div class="eyebrow">TEMUKAN YANG DIBUTUHKAN</div><h2 class="heading">Cari ayat, doa, atau makna</h2><div class="searchbar">${ico('search')}<input id="query" type="search" value="${esc(S.query)}" placeholder="Contoh: ampunan, rezeki, الرَّحْمَٰنِ" autocomplete="off" aria-label="Kata kunci pencarian">${S.query?btn('clear-search',ico('close'),'icon-btn','aria-label="Hapus pencarian"'):''}</div><div class="search-help">Penelusuran meliputi teks Arab, Latin, terjemahan, judul, dan sumber dalam dua dokumen.</div><div class="filter-row">${[['semua','Semua'],['ringkas','Doa pilihan'],['asma','Asmaul Husna'],['intro','Pembukaan'],['outro','Penutup']].map(([k,l])=>btn('filter',l,S.filter===k?'active':'',`data-filter="${k}"`)).join('')}</div><div id="results">${resultsHtml()}</div>`}
function resultsHtml(){let q=normalize(S.query.trim());const arr=indexes.filter(x=>{if(S.filter==='ringkas')return false;if(S.filter!=='semua'&&x.section.type!==S.filter)return false;return !q||x.hay.includes(q)});let selection=arr.slice(0,S.searchLimit).map(x=>{const s=x.section;let snippet='';if(q){let b=s.blocks.find(b=>normalize(b.text||'').includes(q));snippet=b?.text||'';if(snippet.length>220){const pos=Math.max(0,normalize(snippet).indexOf(q));snippet=(pos>40?'…':'')+snippet.slice(Math.max(0,pos-40),pos+130)+'…'}}return `<button class="result" data-action="read" data-id="${esc(s.id)}"><span class="index-n">${s.type==='asma'?s.number:'✦'}</span><span class="txt"><strong>${esc(label(s))}</strong><small>${esc(snippet||secondary(s))}</small></span>${ico('chevron')}</button>`}).join('');const matches=quick.filter(x=>S.filter==='semua'||S.filter==='ringkas').filter(x=>!q||normalize([x.title,x.meaning,x.arabic,x.latin,x.reference].join(' ')).includes(q));return `<p class="fineprint" style="margin-top:0">${arr.length+matches.length} bacaan ditemukan</p>${matches.length?`<div class="search-label">DOA PILIHAN</div><div class="detail-list">${matches.map(quickCard).join('')}</div>`:''}${arr.length?`<div class="search-label">NASKAH LENGKAP</div><div class="detail-list">${selection}</div>${arr.length>S.searchLimit?btn('more','Tampilkan lagi','btn outline','style="margin-top:15px"'):''}`:''}${!arr.length&&!matches.length?empty('Tidak ditemukan','Coba kata lain, atau cari dengan Latin.'):''}`}
function empty(a,b){return `<div class="empty"><div class="emo">☾</div><h3>${esc(a)}</h3><p>${esc(b)}</p>${btn('nav','Jelajahi doa','btn soft','data-target="explore"')}</div>`}
function saved(){const a=S.saved.map(id=>quickMap.get(id)||byId.get(id)).filter(Boolean);return `<div class="eyebrow">PERPUSTAKAAN PRIBADI</div><h2 class="heading">Bacaan tersimpan</h2><p class="fineprint">Bookmark tersimpan di browser perangkat ini, tanpa akun dan tanpa mengunggah data.</p>${a.length?`<div class="detail-list">${a.map(x=>quickMap.has(x.id)?quickCard(x):sectionCard(x)).join('')}</div>`:empty('Belum ada yang disimpan','Saat membaca, ketuk ikon bookmark agar mudah dibuka kembali.')}`}
const reviews=[
 {tag:'Perlu dibedakan',title:'Jumlah 99 nama sahih, susunan daftar tidak otomatis sahih',body:'Hadis Bukhari 2736 dan Muslim 2677 menetapkan keutamaan 99 nama Allah. Namun, versi riwayat yang merinci satu per satu nama di Tirmidzi 3507 dinilai dhaif oleh sebagian pengkaji; sebagian ulama menjelaskan rincian daftar sebagai sisipan perawi (idrāj). Karena itu, susunan nomor dalam dokumen ditampilkan sebagai urutan editorial, bukan daftar baku yang disepakati.',source:[['Bukhari 2736','https://sunnah.com/bukhari:2736'],['Muslim 2677','https://sunnah.com/muslim:2677a'],['Tirmidzi 3507','https://sunnah.com/tirmidhi:3507'],['Bulugh al-Maram 1382','https://sunnah.com/bulugh:1382']]},
 {tag:'Koreksi pengelompokan',title:'QS Yunus 10:29 bukan hadis',body:'Pada Fase 7 terdapat subjudul “Hadis 2: Allah Saksi yang Cukup”, tetapi sumber di bawahnya justru QS Yunus [10]:29. Lafalnya adalah kutipan Al-Qur’an, sehingga kategori teks tersebut seharusnya ayat, bukan hadis. Teks asli dipertahankan dengan pemberitahuan koreksi ini.',source:[['QS Yunus 10:29','https://quran.com/10/29']]},
 {tag:'Teks ganda',title:'Nomor 34 dan 35 tertulis masing-masing dua kali',body:'Dokumen pertama mencantumkan dua versi Al-Ghafūr (34) dan dua versi Asy-Syakūr (35), masing-masing memiliki variasi doa. Agar tidak menghilangkan apa pun, kedua versi tetap dimuat dan diberi penanda V2. Jumlah nama unik tetap 99.',source:[]},
 {tag:'Atribusi ibadah',title:'Doa pribadi bukan otomatis doa ma’tsur',body:'Banyak doa yang panjang dan spesifik (tentang pekerjaan, nominal rezeki, anggota keluarga, dan sebagainya) merupakan susunan penulis. Jangan menyebutnya lafaz Nabi ﷺ atau menetapkan bilangan, waktu, dan keutamaan khusus tanpa dalil. Makna serta gramatika Arab panjang masih membutuhkan telaah ahli.',source:[['QS Al-A’raf 7:180','https://quran.com/7/180']]},
 {tag:'Konteks berubah',title:'Beberapa hajat menyebut tahun dan target spesifik',body:'Dalam dokumen ada target yang menyebut tahun 2026 dan nominal tertentu. Ini dipertahankan sebagai arsip orisinal, tetapi silakan sesuaikan ketika berdoa secara pribadi. Website ini tidak mengubah teks asli secara diam-diam.',source:[]},
 {tag:'Perbedaan waktu doa',title:'Doa umum bukan rangkaian baku setelah salat',body:'Zikir sesudah salam dibuktikan oleh HR Muslim 591 dan 597a. Doa singkat dari Al-Qur’an atau hadis lain tetap dapat dimohonkan sebagai doa umum, tetapi jangan menetapkan satu paket dan bilangan tertentu seolah Nabi ﷺ mewajibkannya setiap selesai salat. Sebagian doa yang disebut “dubur salat” juga dipahami ulama sebagai sebelum salam.',source:[['Muslim 591','https://sunnah.com/muslim:591'],['Abu Dawud 1522','https://sunnah.com/abudawud:1522']]},
 {tag:'Waktu utama',title:'Hujan, sujud, azan–ikamah, Jumat, dan akhir malam',body:'Kami menambahkan waktu utama dengan rujukan spesifik. Doa ketika turun hujan yang sahih: “Allahumma sayyiban nafi‘an” (Bukhari 1032). Keutamaan memperbanyak doa saat sujud (Muslim 482), di antara azan dan ikamah (Abu Dawud 521), saat Jumat (Bukhari 935), dan pada akhir malam (Bukhari 1145).',source:[['Bukhari 1032','https://sunnah.com/bukhari:1032'],['Muslim 482','https://sunnah.com/muslim:482'],['Bukhari 1145','https://sunnah.com/bukhari:1145']]},
 {tag:'Batas verifikasi',title:'Ratusan kutipan belum diaudit satu per satu',body:'Pencantuman nomor hadis atau frasa “Shahih” pada dokumen belum berarti sudah kami verifikasi seluruh sanad, matan, takhrij, maupun kesesuaian lafal. Label dalil di halaman bacaan merupakan referensi dari dokumen, bukan sertifikasi kesahihan. Jangan menggunakan perpustakaan ini sebagai fatwa otomatis.',source:[]}
];
function review(){return `<div class="eyebrow">TRANSPARANSI SUMBER</div><h2 class="heading">Catatan & pemeriksaan</h2><p class="fineprint">Peninjauan terarah atas dokumen. Bukan pengesahan menyeluruh atas seluruh teks Arab, tafsir, atau hadis.</p>${reviews.map((r,i)=>`<article class="card review"><span class="review-number">${String(i+1).padStart(2,'0')}</span><div class="category">${esc(r.tag)}</div><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p>${r.source.length?`<p>${r.source.map(([label,url])=>`<a href="${url}" rel="noopener noreferrer" target="_blank">${esc(label)} ↗</a>`).join(' · ')}</p>`:''}</article>`).join('')}<div class="notice warning">${ico('shield')}<div><strong>Privasi dokumen</strong>Dokumen asli memuat doa dan permohonan pribadi. Jika situs ini diunggah ke hosting publik, seluruh kontennya dapat diakses orang yang mengetahui alamatnya. Gunakan lokal atau hosting yang benar-benar terlindungi.</div></div>`}
function qLink(txt){const m=txt.match(/QS\s+[^\[]*\[(\d+)\]\s*:\s*(\d+)/i);return m?`https://quran.com/${m[1]}/${m[2]}`:null}
function readerEntry(b){if(b.type==='table'){return `<div class="table-wrap"><table><tbody>${b.rows.map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
 let cl=b.type==='label'?(b.text.startsWith('Transliterasi')?' latinlabel':b.text.startsWith('Terjemahan')?' translabel':''):'';
 let p=b.type==='source'?qLink(b.text):null;
 return `<div class="entry ${b.type}${cl}"${b.type==='arabic'?' dir="rtl" lang="ar"':''}>${esc(b.text)}${p?` <a href="${p}" target="_blank" rel="noopener noreferrer" title="Buka ayat untuk membandingkan lafal">↗ Periksa ayat</a>`:''}</div>`
}
function read(){const s=byId.get(S.reader)||secs[0];const index=secs.findIndex(x=>x.id===s.id);const previous=index>=0?secs[index-1]:null,next=index>=0?secs[index+1]:null;const favor=S.saved.includes(s.id);const complete=S.done.includes(s.id);return `<div class="content-width"><div class="reader-head card"><div class="eyebrow">FASE ${String(s.chapter).padStart(2,'0')} · ${esc(chapter(s.chapter).shortTitle)}</div><h2 class="reader-title">${esc(label(s))}</h2>${s.arabicTitle?`<div class="large-ar" lang="ar" dir="rtl">${esc(s.arabicTitle)}</div>`:''}${s.subtitle?`<p class="subtitle">${esc(s.subtitle)}</p>`:''}<div class="reader-meta"><span class="badgetiny">${s.type==='personal'?'Doa pribadi lengkap':s.type==='asma'?'Doa & Asmaul Husna':s.type==='intro'?'Pengantar':'Penutup'}</span><span class="badgetiny">${s.blocks.length} bagian</span>${(s.type==='asma'||s.type==='personal')?'<span class="badgetiny warn">Doa susunan penulis</span>':''}<span class="badgetiny warn">Audit naskah belum menyeluruh</span></div><div class="reader-tools">${btn('save',`${ico('bookmark')} ${favor?'Disimpan':'Simpan'}`,`mini-btn ${favor?'on':''}`)}${btn('done',`${ico('check')} ${complete?'Selesai ✓':'Selesai'}`,`mini-btn ${complete?'on':''}`)}${btn('focus',`${ico('maximize')} ${S.focus?'Keluar fokus':'Fokus'}`,'mini-btn')}${btn('copy',`${ico('share')} Bagikan`,'mini-btn')}</div></div>${s.warnings?.map(w=>`<div class="notice warning" style="margin-bottom:11px">${ico('info')}<div><strong>Catatan naskah</strong>${esc(w)}</div></div>`).join('')||''}<div class="reader-preferences"><div class="pref-top"><div><strong>Pengaturan bacaan</strong><small>Arab ${S.font}px · Latin ${S.latin?'tampil':'sembunyi'} · Arti ${S.translation?'tampil':'sembunyi'}</small></div>${btn('settings',`${ico('settings')} ${S.prefsOpen?'Tutup':'Atur'}`,'mini-btn')}</div>${S.prefsOpen?prefsOptions():''}</div><article class="card reader-body" id="reader-body" aria-label="Isi bacaan">${s.blocks.map(readerEntry).join('')}</article><div class="reading-nav">${previous?btn('read',`${ico('back')} Sebelumnya`,'btn outline',`data-id="${previous.id}"`):'<div></div>'}${next?btn('read',`Selanjutnya ${ico('chevron')}`,'btn',`data-id="${next.id}"`):''}</div><p class="fineprint" style="text-align:center">Dikutip dari naskah asli tanpa perbaikan diam-diam. Periksa tab Catatan untuk koreksi yang telah diketahui.</p></div>`}
function updateTheme(){document.documentElement.dataset.theme=S.dark?'dark':'light';document.documentElement.dataset.palette=S.palette;document.body.style.setProperty('--ar-size',S.font+'px');document.body.style.setProperty('--read-size',S.baseFont+'px');document.body.classList.toggle('hide-latin',!S.latin);document.body.classList.toggle('hide-translation',!S.translation);document.body.classList.toggle('hide-sources',!S.sources);document.body.classList.toggle('focus',S.focus&&(S.view==='read'||S.view==='quickread'))}
function render(scroll=true){updateTheme();const views={home,guide,daily,salatbundle:salatBundle,quickread:quickRead,explore,search,saved,review,read};root.innerHTML=shell(views[S.view]?.()||home());updateTheme();document.title=(S.view==='read'?`${label(byId.get(S.reader)||secs[0])} — `:S.view==='quickread'?`${quickMap.get(S.quickId)?.title||'Doa ringkas'} — `:'')+'Doa Teduh';if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function route(v,opt={}){if(v!=='read'&&v!=='quickread')S.focus=false;S.view=v;Object.assign(S,opt);if(v==='read'&&S.reader){S.last=S.reader;try{history.replaceState({read:S.reader},'',`#baca/${encodeURIComponent(S.reader)}`)}catch(e){location.hash=`baca/${encodeURIComponent(S.reader)}`}}else if(v==='quickread'&&S.quickId){try{history.replaceState({quick:S.quickId},'',`#ringkas/${encodeURIComponent(S.quickId)}`)}catch(e){location.hash=`ringkas/${encodeURIComponent(S.quickId)}`}}else if(location.hash){try{history.replaceState({},'',location.pathname+location.search)}catch(e){location.hash=''}}persist();render()}
function openSection(id){if(!byId.has(id))return;if(S.view!=='read'&&S.view!=='quickread'){S.readingFrom=S.view;S.previousScroll=window.scrollY}route('read',{reader:id})}
function openQuick(id){if(!quickMap.has(id))return;if(S.view!=='read'&&S.view!=='quickread'){S.readingFrom=S.view;S.previousScroll=window.scrollY}route('quickread',{quickId:id})}
function returnFromRead(){S.focus=false;const destination=['home','guide','daily','explore','saved','search','review'].includes(S.readingFrom)?S.readingFrom:'daily';S.view=destination;S.prefsOpen=false;try{history.replaceState({},'',location.pathname+location.search)}catch(e){}persist();render(false);requestAnimationFrame(()=>window.scrollTo({top:S.previousScroll||0,behavior:'instant'}))}
function click(ev){const el=ev.target.closest('[data-action]');if(!el)return;const act=el.dataset.action;const id=el.dataset.id;
 if(act==='nav'){if(el.dataset.target==='guide'&&S.view!=='guide')S.guideStep=0;route(el.dataset.target)}
 else if(act==='salat-open'){S.readingFrom=['home','guide','daily','explore','saved'].includes(S.view)?S.view:'home';route('salatbundle')}
 else if(act==='salat-mode'){const nm=el.dataset.mode==='short'?'short':'full';if(S.salatMode!==nm){S.salatMode=nm;persist();render(false);requestAnimationFrame(()=>document.querySelector('.salat-intro')?.scrollIntoView({block:'start',behavior:'instant'}))}}
 else if(act==='salat-font-up'||act==='salat-font-down'){S.font=Math.max(23,Math.min(49,S.font+(act==='salat-font-up'?2:-2)));persist();updateTheme();announce('Ukuran huruf Arab '+S.font+' piksel')}
 else if(act==='salat-reset'){S.salatDone=[];S.salatCounts={};persist();render(false);requestAnimationFrame(()=>document.querySelector('.salat-intro')?.scrollIntoView({block:'start',behavior:'smooth'}))}
 else if(act==='salat-count'){const key=el.dataset.key,limit=Number(el.dataset.limit),n=Number(el.dataset.n);if(!/^((short|full)-[0-9]+)$/.test(key)||!Number.isInteger(limit)||limit<1||limit>100) return;let current=Math.min(limit,Math.max(0,Number(S.salatCounts[key]||0)));current=Math.min(limit,current+1);S.salatCounts[key]=current;if(current>=limit&&!S.salatDone.includes(key))S.salatDone.push(key);persist();const counter=document.getElementById(`salat-count-${n}`);if(counter)counter.textContent=`${current} / ${limit}`;el.textContent=current>=limit?'Selesai ✓':'+ 1';el.disabled=current>=limit;salatProgressRefresh();if(current>=limit){const card=el.closest('.salat-item');if(card){card.classList.add('complete');card.querySelector('.salat-done-indicator').textContent='✓';const mark=card.querySelector('.salat-mark');if(mark){mark.textContent='✓ Sudah dibaca';mark.classList.add('marked');mark.setAttribute('aria-pressed','true')}}}}
 else if(act==='salat-count-reset'){const key=el.dataset.key;S.salatCounts[key]=0;S.salatDone=S.salatDone.filter(v=>v!==key);persist();const card=el.closest('.salat-item');if(card){card.classList.remove('complete');const ind=card.querySelector('.salat-done-indicator');if(ind){ind.textContent='';ind.setAttribute('aria-label','Belum ditandai')}const mark=card.querySelector('.salat-mark');if(mark){mark.textContent='Tandai dibaca';mark.classList.remove('marked');mark.setAttribute('aria-pressed','false')}const n=el.dataset.n;const text=document.getElementById('salat-count-'+n);if(text)text.textContent='0 / '+card.querySelector('.salat-count-tap')?.dataset.limit;const tap=card.querySelector('.salat-count-tap');if(tap){tap.textContent='+ 1';tap.disabled=false}}salatProgressRefresh()}
 else if(act==='salat-mark'){const key=el.dataset.key;const marked=!S.salatDone.includes(key);S.salatDone=marked?[...S.salatDone,key]:S.salatDone.filter(k=>k!==key);persist();const card=el.closest('.salat-item');if(card){card.classList.toggle('complete',marked);const ind=card.querySelector('.salat-done-indicator');if(ind){ind.textContent=marked?'✓':'';ind.setAttribute('aria-label',marked?'Sudah dibaca':'Belum ditandai')}}el.textContent=marked?'✓ Sudah dibaca':'Tandai dibaca';el.classList.toggle('marked',marked);el.setAttribute('aria-pressed',String(marked));salatProgressRefresh()}
 else if(act==='salat-resume'){const mode=S.salatMode==='short'?'short':'full';const ids=salatData[mode]||[];const n=ids.findIndex((_,i)=>!S.salatDone.includes(`${mode}-${i}`));const target=document.getElementById('salat-step-'+(n<0?ids.length:n+1));target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});if(n<0)announce('Semua bacaan telah ditandai')}
 else if(act==='salat-jump'){document.getElementById(el.dataset.anchor)?.scrollIntoView({behavior:'smooth',block:'start'})}
 else if(act==='salat-next'){document.getElementById('salat-step-'+el.dataset.n)?.scrollIntoView({behavior:'smooth',block:'start'})}
 else if(act==='phase'){S.phase=Number(el.dataset.n);route('explore',{explore:'phase'})}
 else if(act==='phasechip'){S.phase=Number(el.dataset.n);persist();render()}
 else if(act==='explore-tab'){S.explore=el.dataset.tab;persist();render()}
 else if(act==='read')openSection(id);
 else if(act==='quickread')openQuick(id);
 else if(act==='guide-context'){S.guideContext=el.dataset.context;S.guideStep=0;persist();render(false)}
 else if(act==='guide-mode'){S.guideMode=el.dataset.mode;S.guideStep=0;persist();render(false)}
 else if(act==='guide-step'){S.guideStep=Number(el.dataset.step)||0;persist();render(false);requestAnimationFrame(()=>{document.getElementById('guide-reader')?.scrollIntoView({block:'start',behavior:'smooth'})})}
 else if(act==='guide-restart'){S.guideStep=0;persist();render(false);requestAnimationFrame(()=>{document.getElementById('guide-reader')?.scrollIntoView({block:'start',behavior:'smooth'})})}
 else if(act==='daily-filter'){S.dailyCategory=el.dataset.filter;persist();render(false)}
 else if(act==='palette'){S.palette=el.dataset.palette;persist();updateTheme();document.querySelectorAll('.palette-opt').forEach(x=>x.classList.toggle('active',x.dataset.palette===S.palette))}
 else if(act==='return')returnFromRead();
 else if(act==='theme'){S.dark=!S.dark;persist();updateTheme();const theme=el;theme.innerHTML=ico(S.dark?'sun':'moon');theme.setAttribute('aria-label',S.dark?'Mode terang':'Mode gelap')}
 else if(act==='save'){const key=S.view==='quickread'?S.quickId:S.reader;S.saved=S.saved.includes(key)?S.saved.filter(x=>x!==key):[...S.saved,key];persist();render(false);announce(S.saved.includes(key)?'Disimpan ke bookmark':'Dihapus dari bookmark')}
 else if(act==='done'){const key=S.view==='quickread'?S.quickId:S.reader;S.done=S.done.includes(key)?S.done.filter(x=>x!==key):[...S.done,key];persist();render(false);announce(S.done.includes(key)?'Ditandai selesai':'Tanda selesai dibatalkan')}
 else if(act==='focus'){S.focus=!S.focus;persist();render(false);announce(S.focus?'Mode fokus aktif. Ketuk Mode fokus lagi untuk keluar.':'Mode fokus dinonaktifkan')}
 else if(act==='toggle-latin'){S.latin=!S.latin;persist();if(S.view==='salatbundle'){updateTheme();el.textContent=`Latin ${S.latin?'✓':'○'}`;el.setAttribute('aria-pressed',String(S.latin));el.classList.toggle('active',S.latin)}else render(false)}
 else if(act==='toggle-translation'){S.translation=!S.translation;persist();if(S.view==='salatbundle'){updateTheme();el.textContent=`Arti ${S.translation?'✓':'○'}`;el.setAttribute('aria-pressed',String(S.translation));el.classList.toggle('active',S.translation)}else render(false)}
 else if(act==='toggle-sources'){S.sources=!S.sources;persist();render(false)}
 else if(act==='settings'){S.prefsOpen=!S.prefsOpen;render(false)}
 else if(act==='fontsize'){S.baseFont=S.baseFont>=22?15:S.baseFont+1;persist();render(false);announce('Ukuran teks diubah')}
 else if(act==='copytext'){const x=quickMap.get(S.quickId);const t=[x?.title,x?.arabic,x?.latin,x?.meaning,x?.reference].filter(Boolean).join('\n\n');if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t).then(()=>announce('Teks doa disalin')).catch(()=>announce('Tidak dapat menyalin'));else{const box=document.createElement('textarea');box.value=t;document.body.append(box);box.select();try{document.execCommand('copy');announce('Teks doa disalin')}catch(e){announce('Gagal menyalin')}box.remove()}}
 else if(act==='copy'){const link=location.href; if(navigator.clipboard?.writeText){navigator.clipboard.writeText(link).then(()=>announce('Tautan disalin')).catch(()=>announce('Gagal menyalin tautan'))}else announce('Salin alamat pada bilah browser')}
 else if(act==='filter'){S.filter=el.dataset.filter;S.searchLimit=40;render(false);document.getElementById('query')?.focus()}
 else if(act==='clear-search'){S.query='';S.searchLimit=40;render(false);document.getElementById('query')?.focus()}
 else if(act==='more'){S.searchLimit+=50;document.getElementById('results').innerHTML=resultsHtml()}
}
root.addEventListener('click',click);
let searchTimer;root.addEventListener('input',ev=>{if(ev.target.id==='query'){S.query=ev.target.value;S.searchLimit=40;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const r=document.getElementById('results');if(r)r.innerHTML=resultsHtml()},170)}else if(ev.target.id==='fontSlider'){S.font=Number(ev.target.value);document.body.style.setProperty('--ar-size',S.font+'px');document.getElementById('fontNumber').textContent=S.font+'px';persist()}});
window.addEventListener('hashchange',()=>{const qm=location.hash.match(/^#ringkas\/([^?#]+)/);if(qm){try{const id=decodeURIComponent(qm[1]);if(quickMap.has(id)){S.quickId=id;S.view='quickread';render();return}}catch(e){}}const m=location.hash.match(/^#baca\/([^?#]+)/);if(m){let id;try{id=decodeURIComponent(m[1])}catch(e){return}if(byId.has(id)){S.reader=id;S.view='read';S.last=id;render()}}});
window.addEventListener('scroll',()=>{if(!['read','quickread','salatbundle'].includes(S.view))return;const max=document.documentElement.scrollHeight-window.innerHeight;const p=max>0?Math.min(100,window.scrollY/max*100):100;const e=document.getElementById('prog');if(e)e.style.width=p.toFixed(1)+'%'},{passive:true});
window.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&S.focus){S.focus=false;render(false)}});
const quickStart=location.hash.match(/^#ringkas\/([^?#]+)/);if(quickStart){try{const id=decodeURIComponent(quickStart[1]);if(quickMap.has(id)){S.view='quickread';S.quickId=id;S.readingFrom='daily'}}catch(e){}}
const start=location.hash.match(/^#baca\/([^?#]+)/);if(start){try{const id=decodeURIComponent(start[1]);if(byId.has(id)){S.view='read';S.reader=id;S.last=id}}catch(e){}}
render();if('serviceWorker' in navigator && /^https?:/.test(location.protocol)){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js?v=3.7.1').catch(()=>{}))}
};if(window.DOA_DATA)window.startDoaTeduh();
